package datagateway

import (
	"context"
	"encoding/json"
	"net/http"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/apache/arrow-go/v18/arrow"
	"github.com/apache/arrow-go/v18/arrow/array"
	"github.com/apache/arrow-go/v18/arrow/memory"

	pb "github.com/datuplet/datuplet/pkg/datagateway/proto/v2"
)

// The golden file records today's (pre-DuckDB) end-to-end write behaviour per
// Arrow input type; it was generated by the deleted Go buffer path.
const goldenTypesPath = "../../gateway/duckplane/testdata/parquet-types.golden.json"

type goldenReplayEntry struct {
	InputType       string   `json:"input_type"`
	Accepted        bool     `json:"accepted"`
	RejectedAtChunk int      `json:"rejected_at_chunk"`
	RejectedAt      string   `json:"rejected_at"`
	Error           string   `json:"error"`
	Rows            int64    `json:"rows"`
	Values          []string `json:"values"`
}

type goldenReplayInput struct {
	name           string
	dt             arrow.DataType
	chunk1, chunk2 string
}

// goldenReplayInputs are the generator's inputs (two 3-row Arrow-JSON chunks
// per type), copied from the deleted pkg/datagateway/buffer generator.
func goldenReplayInputs() []goldenReplayInput {
	ts := func(name string, unit arrow.TimeUnit, tz, c1, c2 string) goldenReplayInput {
		return goldenReplayInput{name, &arrow.TimestampType{Unit: unit, TimeZone: tz}, c1, c2}
	}
	in := []goldenReplayInput{
		{"int8", arrow.PrimitiveTypes.Int8, `[-128, null, 127]`, `[0, 1, null]`},
		{"int16", arrow.PrimitiveTypes.Int16, `[-32768, null, 32767]`, `[0, 1, null]`},
		{"int32", arrow.PrimitiveTypes.Int32, `[-2147483648, null, 2147483647]`, `[0, 1, null]`},
		{"int64", arrow.PrimitiveTypes.Int64, `[-9223372036854775808, null, 9223372036854775807]`, `[0, 1, null]`},
		{"uint8", arrow.PrimitiveTypes.Uint8, `[0, null, 255]`, `[1, 128, null]`},
		{"uint16", arrow.PrimitiveTypes.Uint16, `[0, null, 65535]`, `[1, 32768, null]`},
		{"uint32", arrow.PrimitiveTypes.Uint32, `[0, null, 4294967295]`, `[1, 2147483648, null]`},
		{"uint64", arrow.PrimitiveTypes.Uint64, `[0, null, 18446744073709551615]`, `[1, 9223372036854775808, null]`},
		{"float32", arrow.PrimitiveTypes.Float32, `[-3.4028235e38, null, 3.4028235e38]`, `[0.5, -0.25, null]`},
		{"float64", arrow.PrimitiveTypes.Float64, `[-1.7976931348623157e308, null, 1.7976931348623157e308]`, `[0.5, -0.25, null]`},
		{"string", arrow.BinaryTypes.String, `["héllo", null, ""]`, `["a", "", null]`},
		{"large_string", arrow.BinaryTypes.LargeString, `["héllo", null, ""]`, `["a", "", null]`},
		{"bool", arrow.FixedWidthTypes.Boolean, `[true, null, false]`, `[false, true, null]`},
	}
	for _, tz := range []string{"", "UTC"} {
		suffix := ""
		if tz != "" {
			suffix = "_tz_utc"
		}
		in = append(in,
			ts("timestamp_s"+suffix, arrow.Second, tz,
				`["1900-01-01T00:00:00Z", null, "2100-01-01T00:00:00Z"]`,
				`["1970-01-01T00:00:00Z", "1969-12-31T23:59:59Z", null]`),
			ts("timestamp_ms"+suffix, arrow.Millisecond, tz,
				`["1900-01-01T00:00:00Z", null, "2100-01-01T00:00:00.123Z"]`,
				`["1970-01-01T00:00:00Z", "1969-12-31T23:59:59.999Z", null]`),
			ts("timestamp_us"+suffix, arrow.Microsecond, tz,
				`["1900-01-01T00:00:00Z", null, "2100-01-01T00:00:00.123456Z"]`,
				`["1970-01-01T00:00:00Z", "1969-12-31T23:59:59.999999Z", null]`),
			ts("timestamp_ns"+suffix, arrow.Nanosecond, tz,
				`["1900-01-01T00:00:00Z", null, "2100-01-01T00:00:00.123456789Z"]`,
				`["1970-01-01T00:00:00Z", "1969-12-31T23:59:59.999999999Z", null]`),
		)
	}
	return append(in,
		goldenReplayInput{"date32", arrow.FixedWidthTypes.Date32, `[-1, null, 19000]`, `[0, 1, null]`},
		goldenReplayInput{"date64", arrow.FixedWidthTypes.Date64, `[-86400000, null, 1641600000000]`, `[0, 86400000, null]`},
		goldenReplayInput{"binary", arrow.BinaryTypes.Binary, `["AP8=", null, ""]`, `["YQ==", "", null]`},
		goldenReplayInput{"large_binary", arrow.BinaryTypes.LargeBinary, `["AP8=", null, ""]`, `["YQ==", "", null]`},
	)
}

// errorClass is an error's leading segment ("buffer error" in
// "buffer error: coalesce append: …").
func errorClass(msg string) string {
	class, _, _ := strings.Cut(msg, ":")
	return class
}

// replayValue renders one received value the way the golden file does (the
// generator read the Parquet back and used ValueStr): timestamps as UTC
// RFC 3339 with the fewest fractional digits, dates as YYYY-MM-DD.
func replayValue(arr arrow.Array, i int) string {
	if arr.IsNull(i) {
		return "(null)"
	}
	switch a := arr.(type) {
	case *array.Timestamp:
		unit := a.DataType().(*arrow.TimestampType).Unit
		return a.Value(i).ToTime(unit).UTC().Format(time.RFC3339Nano)
	case *array.Date32:
		return a.Value(i).ToTime().Format("2006-01-02")
	case *array.Date64:
		return a.Value(i).ToTime().Format("2006-01-02")
	}
	return arr.ValueStr(i)
}

// TestGoldenAcceptanceReplayedThroughServer replays every golden entry as two
// Arrow IPC chunks over the HTTP write endpoint: rejected types fail at the
// recorded chunk with the recorded error class and never reach the plane;
// accepted types reach the plane unchanged (the types today's BufferManager
// accepted, which the DuckDB plane casts per the golden) with the recorded
// values.
func TestGoldenAcceptanceReplayedThroughServer(t *testing.T) {
	raw, err := os.ReadFile(goldenTypesPath)
	if err != nil {
		t.Fatalf("golden: %v", err)
	}
	var g struct {
		Entries []goldenReplayEntry `json:"entries"`
	}
	if err := json.Unmarshal(raw, &g); err != nil {
		t.Fatalf("golden: %v", err)
	}
	golden := map[string]goldenReplayEntry{}
	for _, e := range g.Entries {
		golden[e.InputType] = e
	}
	inputs := goldenReplayInputs()
	if len(inputs) != len(golden) {
		t.Fatalf("%d inputs, %d golden entries", len(inputs), len(golden))
	}
	mem := memory.NewGoAllocator()

	for _, in := range inputs {
		t.Run(in.name, func(t *testing.T) {
			want, ok := golden[in.name]
			if !ok {
				t.Fatal("no golden entry")
			}
			if !want.Accepted && want.RejectedAt != "" {
				t.Fatalf("golden rejects at %q; the replay only covers chunk-time rejections", want.RejectedAt)
			}
			s, p := newWriteTestServer(t, &Config{DefaultBucket: "raw"})
			id := openIPCWriter(t, s, "t")
			sch := arrow.NewSchema([]arrow.Field{{Name: "v", Type: in.dt, Nullable: true}}, nil)

			for i, js := range []string{in.chunk1, in.chunk2} {
				arr, _, err := array.FromJSON(mem, in.dt, strings.NewReader(js))
				if err != nil {
					t.Fatal(err)
				}
				rec := array.NewRecordBatch(sch, []arrow.Array{arr}, int64(arr.Len()))
				arr.Release()
				resp := httpWrite(s, id, ipcPayload(t, rec))
				rec.Release()

				if !want.Accepted && want.RejectedAtChunk == i+1 {
					if resp.Code == http.StatusOK {
						t.Fatalf("chunk %d accepted; golden rejects it: %s", i+1, want.Error)
					}
					e := decodeHTTPError(t, resp)
					if errorClass(e.Error) != errorClass(want.Error) {
						t.Errorf("error %q: class %q, golden %q (%s)", e.Error, errorClass(e.Error), errorClass(want.Error), want.Error)
					}
					if strings.Contains(want.Error, "unsupported Arrow type") && !strings.Contains(e.Error, "unsupported Arrow type") {
						t.Errorf("error %q does not name the unsupported type (golden: %s)", e.Error, want.Error)
					}
					for _, w := range p.writers {
						if n := len(w.recorded()); n != 0 {
							t.Errorf("plane received %d batches of a rejected type", n)
						}
					}
					return
				}
				if resp.Code != http.StatusOK {
					t.Fatalf("chunk %d: %d %s", i+1, resp.Code, resp.Body.String())
				}
			}
			if !want.Accepted {
				t.Fatalf("both chunks accepted; golden rejects at chunk %d: %s", want.RejectedAtChunk, want.Error)
			}

			if len(p.writers) != 1 {
				t.Fatalf("plane writers = %d, want 1", len(p.writers))
			}
			w := p.writers[0]
			if !arrow.TypeEqual(w.spec.Schema.Field(0).Type, in.dt) {
				t.Errorf("writer schema type = %s, want %s", w.spec.Schema.Field(0).Type, in.dt)
			}
			var values []string
			var rows int64
			for _, b := range w.recorded() {
				if !arrow.TypeEqual(b.Schema().Field(0).Type, in.dt) {
					t.Errorf("plane received %s, want %s", b.Schema().Field(0).Type, in.dt)
				}
				rows += b.NumRows()
				for r := 0; r < int(b.NumRows()); r++ {
					values = append(values, replayValue(b.Column(0), r))
				}
			}
			if rows != want.Rows {
				t.Errorf("rows = %d, golden %d", rows, want.Rows)
			}
			if strings.Join(values, "|") != strings.Join(want.Values, "|") {
				t.Errorf("values = %q\ngolden   %q", values, want.Values)
			}
			if _, err := s.CloseWriter(context.Background(), &pb.CloseWriterRequest{WriterId: id}); err != nil {
				t.Errorf("CloseWriter: %v", err)
			}
		})
	}
}
